per_call.cmd:
cat > /app/check_cert.py << 'EOF'
#!/usr/bin/env python3
import os
from datetime import datetime

try:
    from cryptography.x509 import load_pem_x509_certificate
    from cryptography.hazmat.backends import default_backend
    USE_CRYPTOGRAPHY = True
except ImportError:
    USE_CRYPTOGRAPHY = False

def main():
    cert_path = "/app/ssl/server.crt"

    if not os.path.exists(cert_path):
        print(f"Certificate file not found: {cert_path}")
        return False

    try:
        with open(cert_path, "rb") as f:
            cert_data = f.read()

        if USE_CRYPTOGRAPHY:
            cert = load_pem_x509_certificate(cert_data, default_backend())
            subject = cert.subject
            cn = subject.get_attributes_for_oid(cert.oid._name_to_oid.get('commonName') or cert.oid._name_to_oid.get('2.5.4.3'))
            if not cn:
                # Try alternative lookup
                cn = [attr for attr in subject if 'commonName' in str(attr.oid)]
            if cn:
                common_name = str(cn[0].value)
            else:
                common_name = str(subject)

            expiration = cert.not_valid_after_utc
            expiration_date = expiration.strftime("%Y-%m-%d")
        else:
            # Fallback using subprocess
            import subprocess
            result = subprocess.run(
                ["openssl", "x509", "-in", cert_path, "-noout", "-subject", "-enddate"],
                capture_output=True, text=True
            )
            output = result.stdout.strip()
            common_name = ""
            expiration_date = ""
            for line in output.split('\n'):
                if line.startswith("subject="):
                    # Extract CN from subject line
                    for part in line.split(','):
                        if 'CN' in part:
                            common_name = part.split('=')[-1].strip()
                            break
                elif line.startswith("notAfter="):
                    # Parse date like "notAfter=Sep  6 18:17:38 2027 GMT"
                    date_str = line.replace("notAfter=", "").strip()
                    dt = datetime.strptime(date_str, "%b %d %H:%M:%S %Y %Z")
                    expiration_date = dt.strftime("%Y-%m-%d")

        print(f"Certificate Common Name: {common_name}")
        print(f"Certificate Expiration Date: {expiration_date}")
        print("Certificate verification successful")
        return True

    except Exception as e:
        print(f"Error loading certificate: {e}")
        return False

if __name__ == "__main__":
    main()
EOF
